def calculate_k(A, B, D):
    """
    Calculates K, the number of pairs (m, n) such that m in A, n in B, and |m-n| <= D.
    """
    K = 0
    for m in A:
        count_for_m = 0
        for n in B:
            if abs(m - n) <= D:
                count_for_m += 1
        K += count_for_m
    return K

# Define the sets based on the task requirements
A = list(range(1, 2001))  # A = {1, 2, ..., 2000}
B = list(range(-1, 2015)) # B = {-1, 0, 1, ..., 2014}
D = 1000

# Calculate K
K_calculated = calculate_k(A, B, D)

print(f"The calculated value of K is: {K_calculated}")
